package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.FlatMapFunction;
import org.apache.flink.api.common.state.ListState;
import org.apache.flink.api.common.state.ListStateDescriptor;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.common.typeinfo.Types;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.core.fs.FileSystem;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.datastream.SingleOutputStreamOperator;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    // 10 minutes in microseconds
    private static final long SESSION_GAP_MICROS = 10L * 60L * 1000000L;

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Read task events
        SourceFunction<TaskEvent> taskSource = new GzipTaskEventSource(taskInput);
        DataStream<TaskEvent> taskEvents = env.addSource(taskSourceOrTest(taskSource))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forBoundedOutOfOrderness(Duration.ofMinutes(1))
                                .withTimestampAssigner((event, timestamp) -> event.getTimestamp() / 1000)
                );

        // Read job events
        SourceFunction<JobEvent> jobSource = new GzipJobEventSource(jobInput);
        DataStream<JobEvent> jobEvents = env.addSource(jobSourceOrTest(jobSource))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forBoundedOutOfOrderness(Duration.ofMinutes(1))
                                .withTimestampAssigner((event, timestamp) -> event.getTimestamp() / 1000)
                );

        // Filter only SUBMIT events from task events
        DataStream<TaskEvent> submitEvents = taskEvents
                .filter(event -> event.getEventType() == TaskEvent.SUBMIT);

        // Filter only job finish events (FINISH, FAIL, KILL)
        DataStream<JobEvent> finishEvents = jobEvents
                .filter(JobEvent::isJobFinished);

        // Connect task submit events with job finish events
        SingleOutputStreamOperator<Tuple2<Long, Integer>> result = submitEvents
                .keyBy(TaskEvent::getJobId)
                .connect(finishEvents.keyBy(JobEvent::getJobId))
                .process(new SessionCalculator());

        // Write output
        result.map(t -> "(" + t.f0 + "," + t.f1 + ")")
                .writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE)
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    public static class SessionCalculator
            extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, Tuple2<Long, Integer>> {

        // Store submit timestamps
        private transient ListState<Long> submitTimestamps;
        // Flag if job is finished
        private transient ValueState<Boolean> jobFinished;

        @Override
        public void open(Configuration parameters) {
            submitTimestamps = getRuntimeContext().getListState(
                    new ListStateDescriptor<>("submitTimestamps", Long.class));
            jobFinished = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("jobFinished", Boolean.class));
        }

        @Override
        public void processElement1(TaskEvent event, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            // Store submit timestamp
            submitTimestamps.add(event.getTimestamp());
        }

        @Override
        public void processElement2(JobEvent event, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            // Job finished, calculate the longest session
            Boolean finished = jobFinished.value();
            if (finished != null && finished) {
                return; // Already processed this job
            }
            jobFinished.update(true);

            // Get all submit timestamps
            List<Long> timestamps = new ArrayList<>();
            for (Long ts : submitTimestamps.get()) {
                timestamps.add(ts);
            }

            if (timestamps.isEmpty()) {
                return;
            }

            // Sort timestamps
            timestamps.sort(Comparator.naturalOrder());

            // Calculate sessions - a session is a period of submits within 10 min gaps
            int maxSessionSize = 0;
            int currentSessionSize = 1;

            for (int i = 1; i < timestamps.size(); i++) {
                long gap = timestamps.get(i) - timestamps.get(i - 1);
                if (gap <= SESSION_GAP_MICROS) {
                    currentSessionSize++;
                } else {
                    maxSessionSize = Math.max(maxSessionSize, currentSessionSize);
                    currentSessionSize = 1;
                }
            }
            maxSessionSize = Math.max(maxSessionSize, currentSessionSize);

            out.collect(new Tuple2<>(ctx.getCurrentKey(), maxSessionSize));
        }
    }

    public static class GzipTaskEventSource implements SourceFunction<TaskEvent> {
        private final String filePath;
        private volatile boolean isRunning = true;

        public GzipTaskEventSource(String filePath) {
            this.filePath = filePath;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            try (BufferedReader reader = new BufferedReader(
                    new InputStreamReader(
                            new GZIPInputStream(
                                    new java.io.FileInputStream(filePath))))) {
                String line;
                while (isRunning && (line = reader.readLine()) != null) {
                    TaskEvent event = TaskEvent.fromString(line);
                    if (event != null) {
                        ctx.collect(event);
                    }
                }
            }
        }

        @Override
        public void cancel() {
            isRunning = false;
        }
    }

    public static class GzipJobEventSource implements SourceFunction<JobEvent> {
        private final String filePath;
        private volatile boolean isRunning = true;

        public GzipJobEventSource(String filePath) {
            this.filePath = filePath;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            try (BufferedReader reader = new BufferedReader(
                    new InputStreamReader(
                            new GZIPInputStream(
                                    new java.io.FileInputStream(filePath))))) {
                String line;
                while (isRunning && (line = reader.readLine()) != null) {
                    JobEvent event = JobEvent.fromString(line);
                    if (event != null) {
                        ctx.collect(event);
                    }
                }
            }
        }

        @Override
        public void cancel() {
            isRunning = false;
        }
    }
}

