# Find task SUBMIT job IDs that also have a job FINISH event
TASK_SUBMIT_JOBS=$(zcat /app/workspace/data/task_events/*.csv.gz | awk -F',' '$6=="0" {print $3}' | sort -u)
JOB_FINISH_JOBS=$(zcat /app/workspace/data/job_events/*.csv.gz | awk -F',' '$4=="3" || $4=="4" || $4=="5" {print $3}' | sort -u)

echo "Task SUBMIT job count:" $(echo "$TASK_SUBMIT_JOBS" | wc -l)
echo "Job FINISH job count:" $(echo "$JOB_FINISH_JOBS" | wc -l)

# Find common
COMMON=$(comm -12 <(echo "$TASK_SUBMIT_JOBS") <(echo "$JOB_FINISH_JOBS"))
echo "Common job count:" $(echo "$COMMON" | grep -c '[0-9]' || echo 0)
echo "Sample common jobs:"
echo "$COMMON" | head -5
